class ApplicationCycle{constructor(){this.elapsed=0;this.key='';}reset(){this.elapsed=0;this.key='';}next({apps,current,dt,paused}){const a=apps.find(x=>x.business.id===current)||apps[0],limit=C.anomaly(a?.state)?30:10,key=(a?.business.id||'')+':'+limit;if(key!==this.key){this.key=key;this.elapsed=0;}if(paused||!a||apps.length<2)return null;this.elapsed+=Math.max(0,Math.min(dt,1));if(this.elapsed<limit)return null;this.elapsed=0;return apps[(apps.indexOf(a)+1)%apps.length].business.id;}}
